(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-870":{scenario:{company:"Ngân Hà Language Solutions",supervisor:{name:"Trịnh Quốc Việt",role:{vi:"Trưởng phòng Chất lượng Biên dịch",en:"Translation Quality Manager"}},ref_code:"TR-5521",title:{vi:"Đúng quy trình. Đúng báo giá. Đúng bảo mật.",en:"Right workflow. Right quote. Right confidentiality."},brief:{vi:"Bạn kiểm tra hồ sơ dự án TR-5521: dịch sổ tay vận hành máy nén khí công nghiệp từ tiếng Anh sang tiếng Việt, 12.400 từ nguồn. Phân tích bộ nhớ dịch: 6.800 từ mới, 3.200 từ khớp mờ 75-99%, 2.400 từ khớp 100%. Đơn giá hợp đồng 1.200 VND/từ (số liệu mô phỏng). Đối chiếu phiếu dự án nháp với hợp đồng và quy trình chất lượng đã duyệt, sửa bước kiểm soát bắt buộc sau khi dịch và giá trị báo giá (VND), rồi lập báo cáo có căn cứ.",en:"You are checking project file TR-5521: translating an industrial air compressor operating manual from English into Vietnamese, 12,400 source words. Translation memory analysis: 6,800 new words, 3,200 fuzzy matches at 75-99%, 2,400 exact 100% matches. Contract rate 1,200 VND per word (training data). Compare the draft project sheet with the contract and the approved quality workflow, correct the mandatory post-translation control step and the quote value (VND), then write an evidence-based report."},reference_title:{vi:"Hợp đồng dịch vụ & quy trình chất lượng đã duyệt · TR-5521",en:"Approved service contract & quality workflow · TR-5521"},fields:[{id:"QA_STEP",label:{vi:"Bước kiểm soát bắt buộc sau khi dịch",en:"Mandatory post-translation control"},initial:"SELF-CHECK",expected:"REVISION",choices:["SELF-CHECK","REVIEW","REVISION"],reference:"Quy trình chất lượng biên dịch",hint:{vi:"Phân biệt: tự kiểm tra của người dịch, hiệu đính song ngữ bởi người thứ hai và rà soát đơn ngữ bản đích.",en:"Distinguish the translator's own check, bilingual revision by a second linguist and monolingual review of the target."}},{id:"QUOTE_VND",label:{vi:"Giá trị báo giá (VND)",en:"Quote value (VND)"},initial:"14880000",expected:"11328000",reference:"Phụ lục đơn giá hợp đồng",ref_value:{vi:"Phân tích bộ nhớ dịch: 6.800 từ mới, 3.200 khớp mờ, 2.400 khớp 100%; đơn giá 1.200 VND/từ",en:"TM analysis: 6,800 new, 3,200 fuzzy, 2,400 exact matches; rate 1,200 VND per word"},hint:{vi:"Hợp đồng không tính mọi từ theo giá đầy đủ: mỗi mức khớp bộ nhớ dịch có hệ số riêng.",en:"The contract does not bill every word at full rate: each TM match band has its own weight."}}],sop32:{vi:"Số từ quy đổi = từ mới x 100% + khớp mờ 75-99% x 60% + khớp 100% x 30%; giá trị báo giá = số từ quy đổi x đơn giá hợp đồng (số liệu mô phỏng).",en:"Weighted words = new words x 100% + fuzzy 75-99% x 60% + exact 100% x 30%; quote value = weighted words x contract rate (training data)."},context:{label:"CAT / TR-5521",metrics:[{label:{vi:"Tổng từ nguồn",en:"Total source words"},value:"12,400"},{label:{vi:"Mới / khớp mờ / khớp 100%",en:"New / fuzzy / exact"},value:"6,800 / 3,200 / 2,400"},{label:{vi:"Đơn giá mô phỏng",en:"Training rate"},value:"1,200 VND/word"}]},crisis:{vi:"Quản lý dự án nhắn: “Dán cả sổ tay vào trang dịch máy miễn phí trên mạng cho nhanh, bỏ bước hiệu đính, giao khách là bản dịch do người làm. Khách cần trước 8 giờ sáng mai.” Tài liệu có điều khoản bảo mật.",en:"The project manager writes: “Paste the whole manual into a free online machine translation site, skip revision and deliver it as human translation. The client needs it before 8 a.m. tomorrow.” The document is under a confidentiality clause."},options:{safe:{vi:"Từ chối đưa tài liệu lên công cụ công cộng và giao bản không hiệu đính, báo Trưởng phòng Chất lượng; đề xuất chia việc, dùng công cụ dịch máy được khách chấp thuận có hiệu đính sau dịch máy hoặc xin lùi hạn.",en:"Refuse to upload the document to a public tool or deliver unrevised work, inform the Quality Manager; propose splitting the work, a client-approved MT engine with post-editing or a deadline extension."},shortcut:{vi:"Dùng dịch máy miễn phí, sửa sơ qua và giao khách là bản dịch người làm cho kịp hạn.",en:"Use free machine translation, skim-edit it and deliver it as human work to meet the deadline."},wait:{vi:"Không làm gì và chờ quản lý dự án tự tìm người dịch khác.",en:"Do nothing and wait for the project manager to find another translator."}},questions:{vi:["Vì sao bước bắt buộc là REVISION và báo giá đúng là 11328000 VND? Trình bày căn cứ từ quy trình và hợp đồng.","Đưa tài liệu mật lên công cụ dịch công cộng và giao bản dịch máy như bản người dịch gây những rủi ro gì? Bạn xử lý hạn gấp thế nào?"],en:["Why is REVISION the mandatory step and why is the correct quote 11328000 VND? Cite the workflow and contract.","What risks come from uploading confidential files to public MT and passing machine output off as human translation? How do you handle the tight deadline?"]},hints:{vi:["Đặt phiếu dự án nháp cạnh quy trình chất lượng và xác định bước nào do người thứ hai thực hiện.","Áp dụng SOP mục 3.2: nhân từng nhóm từ với hệ số tương ứng trước khi nhân đơn giá.","Đọc lại SOP mục 4.2: tài liệu có điều khoản bảo mật chỉ được xử lý trên công cụ đã được phê duyệt."],en:["Place the draft project sheet next to the quality workflow and identify the step done by a second person.","Apply SOP 3.2: weight each word band before multiplying by the rate.","Re-read SOP 4.2: confidential documents may be processed only in approved tools."]}},learning:{summary:{vi:"Biên - phiên dịch viên thương mại và kỹ thuật chuyển ngữ chính xác hợp đồng, tài liệu kỹ thuật, hồ sơ thầu, tài liệu marketing và phiên dịch trong đàm phán, hội thảo, đào tạo. Công việc đòi hỏi năng lực song ngữ cao, kiến thức chuyên ngành, quản lý thuật ngữ, thành thạo công cụ CAT, tuân thủ quy trình chất lượng và cam kết bảo mật thông tin khách hàng.",en:"A commercial and technical translator and interpreter accurately renders contracts, technical documents, tenders and marketing materials and interprets in negotiations, conferences and training. The work demands high bilingual competence, domain knowledge, terminology management, mastery of CAT tools, quality workflow compliance and strict client confidentiality."},responsibilities:{vi:["Phân tích tài liệu nguồn, xây dựng bảng thuật ngữ và câu hỏi làm rõ với khách hàng.","Biên dịch trên công cụ CAT, tận dụng bộ nhớ dịch và bảo đảm nhất quán thuật ngữ.","Hiệu đính chéo, kiểm tra QA tự động về số liệu, đơn vị, thẻ định dạng và thuật ngữ.","Phiên dịch nối tiếp hoặc song song trong họp, đàm phán, đào tạo kỹ thuật.","Lập báo giá theo phân tích bộ nhớ dịch, quản lý hạn giao và lưu trữ an toàn tài liệu."],en:["Analyze source documents, build glossaries and raise queries with the client.","Translate in CAT tools, leverage translation memory and keep terminology consistent.","Cross-revise and run automated QA on numbers, units, tags and terminology.","Interpret consecutively or simultaneously in meetings, negotiations and technical training.","Quote from TM analysis, manage deadlines and store documents securely."]},competencies:[{name:{vi:"Năng lực song ngữ chuyên ngành",en:"Specialized bilingual competence"},desc:{vi:"Hiểu sâu cấu trúc, văn phong pháp lý, kỹ thuật ở cả hai ngôn ngữ và chọn từ chính xác.",en:"Master legal and technical structures and styles in both languages and choose precise terms."}},{name:{vi:"Quản lý thuật ngữ",en:"Terminology management"},desc:{vi:"Xây dựng, cập nhật termbase và bảo đảm thuật ngữ nhất quán trong toàn dự án.",en:"Build and update termbases and keep terminology consistent across the project."}},{name:{vi:"Công nghệ dịch thuật",en:"Translation technology"},desc:{vi:"Thành thạo CAT, bộ nhớ dịch, QA tự động và hiệu đính sau dịch máy có kiểm soát.",en:"Master CAT tools, translation memory, automated QA and controlled MT post-editing."}},{name:{vi:"Kỹ năng phiên dịch",en:"Interpreting skills"},desc:{vi:"Ghi nhớ ngắn hạn, ghi chép nhanh, xử lý áp lực và giữ trung lập khi phiên dịch.",en:"Use short-term memory, fast note-taking, composure and neutrality when interpreting."}},{name:{vi:"Bảo mật & liêm chính",en:"Confidentiality & integrity"},desc:{vi:"Giữ bí mật tài liệu, minh bạch về dịch máy và từ chối làm sai lệch nội dung.",en:"Keep documents confidential, be transparent about MT use and refuse to distort content."}}],knowledge:{vi:["ISO 17100:2015 về dịch vụ biên dịch: hiệu đính (revision) bởi người thứ hai là bước bắt buộc.","ISO 18587:2017 về hiệu đính bản dịch máy (post-editing) và yêu cầu năng lực người hiệu đính.","ISO 18841:2018 về yêu cầu chung đối với dịch vụ phiên dịch.","Nghị định 23/2015/NĐ-CP về chứng thực, trong đó có chứng thực chữ ký người dịch.","Các hình thức phiên dịch: nối tiếp, song song (cabin), thì thầm, dịch nhìn văn bản."],en:["ISO 17100:2015 on translation services: revision by a second person is a mandatory step.","ISO 18587:2017 on post-editing of machine translation output and post-editor competence.","ISO 18841:2018 on general requirements for interpreting services.","Decree 23/2015/ND-CP on certification, including certification of the translator's signature.","Interpreting modes: consecutive, simultaneous (booth), whispered and sight translation."]},tools:["Phần mềm CAT có bộ nhớ dịch và termbase","Công cụ QA thuật ngữ và số liệu","Công cụ dịch máy được khách chấp thuận","Thiết bị phiên dịch cabin","Phần mềm so sánh và căn chỉnh văn bản","Kho lưu trữ tài liệu mã hóa"],kpis:{vi:["Số lỗi nghiêm trọng trên 1.000 từ theo thang đánh giá chất lượng.","Tỷ lệ dự án giao đúng hạn.","Mức nhất quán thuật ngữ khi kiểm tra QA tự động.","Số sự cố bảo mật tài liệu (mục tiêu bằng 0)."],en:["Major errors per 1,000 words on the quality scorecard.","Share of projects delivered on time.","Terminology consistency in automated QA.","Document confidentiality incidents (target zero)."]},day:[{time:"08:00",vi:"Nhận dự án, chạy phân tích bộ nhớ dịch và lập báo giá theo phụ lục đơn giá.",en:"Receive projects, run TM analysis and quote from the rate appendix."},{time:"09:30",vi:"Biên dịch hợp đồng, tra cứu thuật ngữ và ghi câu hỏi cần khách làm rõ.",en:"Translate a contract, research terms and log queries for the client."},{time:"13:30",vi:"Phiên dịch nối tiếp buổi đàm phán kỹ thuật giữa hai đối tác.",en:"Interpret consecutively at a technical negotiation between two partners."},{time:"15:30",vi:"Hiệu đính bản dịch của đồng nghiệp và chạy QA số liệu, đơn vị, thuật ngữ.",en:"Revise a colleague's translation and run QA on numbers, units and terms."},{time:"17:00",vi:"Cập nhật termbase, bộ nhớ dịch và lưu trữ tài liệu theo quy định bảo mật.",en:"Update the termbase and TM and archive files under the security policy."}],mistakes:{vi:["Chỉ tự kiểm tra rồi giao khách, bỏ bước hiệu đính bởi người thứ hai.","Báo giá toàn bộ số từ theo giá đầy đủ, bỏ qua hệ số khớp bộ nhớ dịch đã thỏa thuận.","Đưa tài liệu mật lên công cụ dịch máy công cộng, vi phạm cam kết bảo mật."],en:["Delivering after a self-check only, skipping revision by a second linguist.","Quoting all words at full rate and ignoring the agreed TM match weights.","Uploading confidential documents to public MT tools, breaching confidentiality."]},career:[{vi:"Biên dịch viên tập sự",en:"Junior translator"},{vi:"Biên - phiên dịch viên chuyên ngành",en:"Specialized translator & interpreter"},{vi:"Hiệu đính viên cao cấp & phiên dịch hội nghị",en:"Senior reviser & conference interpreter"},{vi:"Trưởng phòng chất lượng & quản lý dịch vụ ngôn ngữ",en:"Language services & quality manager"}],glossary:[{term:"Revision",vi:"Hiệu đính song ngữ: người thứ hai so bản dịch với bản nguồn để sửa lỗi nghĩa, thuật ngữ, văn phong.",en:"Bilingual examination by a second linguist comparing target and source to fix meaning, terms and style."},{term:"Translation memory",vi:"Bộ nhớ dịch lưu các cặp câu nguồn - đích đã dịch để tái sử dụng.",en:"A database of previously translated source-target segments for reuse."},{term:"Fuzzy match",vi:"Khớp mờ: câu mới giống một phần câu đã có trong bộ nhớ dịch, ví dụ 75-99%.",en:"A new segment partly matching a stored segment, for example 75-99%."},{term:"Termbase",vi:"Cơ sở thuật ngữ đã duyệt kèm định nghĩa và ngữ cảnh sử dụng.",en:"An approved terminology database with definitions and usage context."},{term:"Post-editing",vi:"Hiệu đính bản dịch máy để đạt chất lượng đã thỏa thuận với khách hàng.",en:"Editing machine translation output to reach the quality agreed with the client."}],quiz:[{q:{vi:"Dự án có 5.000 từ mới, 2.000 khớp mờ (hệ số 60%), 1.000 khớp 100% (hệ số 30%), đơn giá 1.000 VND/từ. Báo giá là bao nhiêu?",en:"A project has 5,000 new words, 2,000 fuzzy (60% weight), 1,000 exact (30% weight), rate 1,000 VND per word. What is the quote?"},options:{vi:["8.000.000 VND","6.500.000 VND","7.100.000 VND","5.900.000 VND"],en:["8,000,000 VND","6,500,000 VND","7,100,000 VND","5,900,000 VND"]},answer:1,explain:{vi:"Từ quy đổi = 5.000 + 2.000 x 60% + 1.000 x 30% = 6.500; báo giá = 6.500 x 1.000 = 6.500.000 VND.",en:"Weighted words = 5,000 + 2,000 x 60% + 1,000 x 30% = 6,500; quote = 6,500 x 1,000 = 6,500,000 VND."}},{q:{vi:"Theo ISO 17100, bước nào bắt buộc phải do người khác người dịch thực hiện?",en:"Under ISO 17100, which step must be done by someone other than the translator?"},options:{vi:["Tự kiểm tra","Đếm từ","Rà soát đơn ngữ","Hiệu đính song ngữ (revision)"],en:["Self-check","Word count","Monolingual review","Bilingual revision"]},answer:3,explain:{vi:"ISO 17100 yêu cầu hiệu đính song ngữ bởi người thứ hai; rà soát đơn ngữ là tùy chọn.",en:"ISO 17100 requires bilingual revision by a second person; monolingual review is optional."}},{q:{vi:"Hình thức phiên dịch nào thường cần cabin và tai nghe cho hội nghị lớn?",en:"Which interpreting mode usually needs booths and headsets for large conferences?"},options:{vi:["Phiên dịch song song","Phiên dịch nối tiếp","Dịch nhìn văn bản","Phiên dịch thì thầm"],en:["Simultaneous interpreting","Consecutive interpreting","Sight translation","Whispered interpreting"]},answer:0,explain:{vi:"Phiên dịch song song diễn ra gần như cùng lúc với người nói, cần cabin cách âm và hệ thống tai nghe.",en:"Simultaneous interpreting runs almost in real time and needs soundproof booths and headsets."}},{q:{vi:"Quản lý dự án yêu cầu đưa tài liệu mật lên trang dịch máy miễn phí cho kịp hạn. Bạn làm gì?",en:"The PM asks you to upload a confidential file to a free MT site to meet the deadline. What do you do?"},options:{vi:["Làm theo vì kịp hạn quan trọng nhất","Chỉ đưa lên một nửa tài liệu","Từ chối, báo cáo và đề xuất công cụ được duyệt hoặc xin lùi hạn","Xóa tên khách rồi đưa lên"],en:["Comply since the deadline matters most","Upload only half the document","Refuse, escalate and propose an approved tool or an extension","Remove the client name and upload it"]},answer:2,explain:{vi:"Công cụ công cộng có thể lưu dữ liệu, vi phạm bảo mật; phải dùng công cụ được phê duyệt và minh bạch với khách.",en:"Public tools may store data and breach confidentiality; use approved tools and be transparent with the client."}}],tools_en:["CAT tool with translation memory and termbase","Terminology and number QA tools","Client-approved machine translation tools","Interpreting booth equipment","Text comparison and alignment software","Encrypted document repository"]}}})})(window.KKR);
